import{f as a,D as r,o as d,c as s,k as n,a as i,G as m,ar as o}from"./chunks/framework.HWAOx3Ef.js";const p=JSON.parse('{"title":"Vergabe von Stimmen auf dem Stimmzettel","description":"","frontmatter":{},"headers":[],"relativePath":"technik/adr/ui/adr010-dse-stimmvergabe-stimmen-ergaenzen.md","filePath":"technik/adr/ui/adr010-dse-stimmvergabe-stimmen-ergaenzen.md"}'),u={name:"technik/adr/ui/adr010-dse-stimmvergabe-stimmen-ergaenzen.md"};function h(l,e,g,b,c,z){const t=r("adr-status");return d(),s("div",null,[e[0]||(e[0]=n("h1",{id:"vergabe-von-stimmen-auf-dem-stimmzettel",tabindex:"-1"},[i("Vergabe von Stimmen auf dem Stimmzettel "),n("a",{class:"header-anchor",href:"#vergabe-von-stimmen-auf-dem-stimmzettel","aria-label":'Permalink to "Vergabe von Stimmen auf dem Stimmzettel"'},"​")],-1)),e[1]||(e[1]=n("h2",{id:"status",tabindex:"-1"},[i("Status "),n("a",{class:"header-anchor",href:"#status","aria-label":'Permalink to "Status"'},"​")],-1)),m(t,{status:"accepted"}),e[2]||(e[2]=o('<h2 id="kontext" tabindex="-1">Kontext <a class="header-anchor" href="#kontext" aria-label="Permalink to &quot;Kontext&quot;">​</a></h2><p>Die wählende Person vergibt ihre Stimmen auf dem Stimmzettel. Dies wird in der Anwendung durch eine Tastatureingabe ermöglicht.<br> Damit das möglichst nachvollziehbar für die User*innen ist, werden folgende Regeln definiert.</p><h2 id="entscheidung" tabindex="-1">Entscheidung <a class="header-anchor" href="#entscheidung" aria-label="Permalink to &quot;Entscheidung&quot;">​</a></h2><h3 id="einzelstimmenvergabe" tabindex="-1">Einzelstimmenvergabe <a class="header-anchor" href="#einzelstimmenvergabe" aria-label="Permalink to &quot;Einzelstimmenvergabe&quot;">​</a></h3><p>Bekommt ein*e Kandidat*in, der*die bereits eine Einzelstimme hat, erneut eine Einzelstimme vergeben, so wird diese zur bestehenden Stimme dazuaddiert.</p><p>Hat ein*e Kandidat*in mehrere Nennungen und die zweite Nennung hat zum Beispiel bereits eine Stimme, so führt die Eingabe einer Einzelstimme bei dieser Person zu einer weiteren Stimme bei der zweiten Nennung.</p><p>Hat ein*e Kandidat*in noch keine Einzelstimmen erhalten, wird eine Stimme auf die erste freie Nennung vergeben. Gibt es keine Nennung ohne Streichung, bekommt die erste Nennung des\\der Kandidaten*in die Einzelstimme.</p><p>Hat ein*e Kandidat*in zum Beispiel drei Nennungen und die erste wurde zuvor gestrichen, wird auf die zweite Nennung eine Stimme vergeben.</p><h3 id="vergabe-von-listenkreuzen" tabindex="-1">Vergabe von Listenkreuzen <a class="header-anchor" href="#vergabe-von-listenkreuzen" aria-label="Permalink to &quot;Vergabe von Listenkreuzen&quot;">​</a></h3><p>Die Vergabe von Listenkreuzen setzt den Zustand bei einem Wahlvorschlag. Ist bereits ein Listenkreuz gesetzt, bleibt dieses erhalten. Ist kein Listenkreuz gesetzt, wird ein Listenkreuz gesetzt.</p><h3 id="streichungen-von-kandidat-innen" tabindex="-1">Streichungen von Kandidat*innen <a class="header-anchor" href="#streichungen-von-kandidat-innen" aria-label="Permalink to &quot;Streichungen von Kandidat\\*innen&quot;">​</a></h3><p>Soll ein*e Kandidat*in über die Tastatur gestrichen werden, wird die erste freie Nennung ohne Einzelstimme oder Streichung gestrichen.</p><p>Hat ein*e Kandidat*in bereits Einzelstimmen erhalten, erfolgt die Streichung bei der ersten freien Nennung ohne Streichung. Haben alle Nennungen Einzelstimmen oder eine Streichung wird die erste Nennung ohne Streichung gestrichen.</p><p>Bei ein*er Kandidat*in mit drei Nennungen, bei der die erste Nennung bereits eine Einzelstimme hat und die zweite Nennung gestrichen wurde, führt die Eingabe des Befehls zur Vergabe einer Streichung bei der dritten Nennung.</p><p>Gibt es keine Nennung ohne Streichung, bekommt der*die User*in einen Hinweis, dass keine Streichung durchgeführt werden kann.</p><h2 id="konsequenzen" tabindex="-1">Konsequenzen <a class="header-anchor" href="#konsequenzen" aria-label="Permalink to &quot;Konsequenzen&quot;">​</a></h2><h3 id="positiv" tabindex="-1">positiv <a class="header-anchor" href="#positiv" aria-label="Permalink to &quot;positiv&quot;">​</a></h3><p>Eine intuitivere Bedienung der Anwendung bei Erfassungen von Stimmen mit der Tastatur.</p><h3 id="negativ" tabindex="-1">negativ <a class="header-anchor" href="#negativ" aria-label="Permalink to &quot;negativ&quot;">​</a></h3><p>Eine Verteilung von Einzelstimmen auf verschiedene Nennungen ein*er Kandidat*in erfordert mehr Aufwand.</p>',20))])}const f=a(u,[["render",h]]);export{p as __pageData,f as default};
